            t_aw3_p3_012 = -cs267*cs270*cs83 - cs273*cs288*d_a(1) - cs275*cs287*d_a(1)
            aw3(1, 2, 3, 3) = t_aw3_p3_012
            aw3(1, 3, 2, 3) = t_aw3_p3_012
