            t_aw3_q_001 = -cs27*cs300 - cs28*cs307 - cs309*cs310
            aw3(1, 1, 2, 4) = t_aw3_q_001
            aw3(1, 2, 1, 4) = t_aw3_q_001
            aw3(2, 1, 1, 4) = t_aw3_q_001
            t_aw3_q_002 = -cs300*cs31 - cs307*cs32 - cs311*cs312
            aw3(1, 1, 3, 4) = t_aw3_q_002
            aw3(1, 3, 1, 4) = t_aw3_q_002
            aw3(3, 1, 1, 4) = t_aw3_q_002
            t_aw3_q_011 = -cs304*cs309 - cs316*cs317 - cs319*cs320
            aw3(1, 2, 2, 4) = t_aw3_q_011
