            awr3(1, 2, 1, 1) = t_awr3_p1_001
            awr3(2, 1, 1, 1) = t_awr3_p1_001
            t_awr3_p1_002 = cs57*d_a(3)
            awr3(1, 1, 3, 1) = t_awr3_p1_002
            awr3(1, 3, 1, 1) = t_awr3_p1_002
            awr3(3, 1, 1, 1) = t_awr3_p1_002
            t_awr3_p1_011 = cs55*cs62
            awr3(1, 2, 2, 1) = t_awr3_p1_011
