            awr3(3, 3, 1, 1) = t_awr3_p1_022
            awr3(2, 2, 2, 1) = cs70*(cs20*(3.0_wp - cs59) - cs47 - cs61)
            t_awr3_p1_112 = cs62*cs64
            awr3(2, 2, 3, 1) = t_awr3_p1_112
            awr3(2, 3, 2, 1) = t_awr3_p1_112
            awr3(3, 2, 2, 1) = t_awr3_p1_112
            t_awr3_p1_122 = cs69*cs70
            awr3(2, 3, 3, 1) = t_awr3_p1_122
            awr3(3, 2, 3, 1) = t_awr3_p1_122
            awr3(3, 3, 2, 1) = t_awr3_p1_122
            awr3(3, 3, 3, 1) = cs64*(cs20*(3.0_wp - cs66) - cs47 - cs68)
            awr3(1, 1, 1, 2) = cs75*(cs20*(3.0_wp - cs71) - cs72 - cs73)
            t_awr3_p2_001 = cs77*d_a(2)
            awr3(1, 1, 2, 2) = t_awr3_p2_001
            awr3(1, 2, 1, 2) = t_awr3_p2_001
            awr3(2, 1, 1, 2) = t_awr3_p2_001
            t_awr3_p2_002 = cs77*d_a(3)
            awr3(1, 1, 3, 2) = t_awr3_p2_002
            awr3(1, 3, 1, 2) = t_awr3_p2_002
            awr3(3, 1, 1, 2) = t_awr3_p2_002
            t_awr3_p2_011 = cs75*cs80
            awr3(1, 2, 2, 2) = t_awr3_p2_011
            awr3(2, 1, 2, 2) = t_awr3_p2_011
            awr3(2, 2, 1, 2) = t_awr3_p2_011
            t_awr3_p2_012 = cs27*cs81*(-2.0_wp*cs18 - 4.0_wp/9.0_wp*cs63 - 3.0_wp)
            awr3(1, 2, 3, 2) = t_awr3_p2_012
            awr3(1, 3, 2, 2) = t_awr3_p2_012
            awr3(2, 1, 3, 2) = t_awr3_p2_012
            awr3(2, 3, 1, 2) = t_awr3_p2_012
            awr3(3, 1, 2, 2) = t_awr3_p2_012
            awr3(3, 2, 1, 2) = t_awr3_p2_012
            t_awr3_p2_022 = cs75*cs84
            awr3(1, 3, 3, 2) = t_awr3_p2_022
            awr3(3, 1, 3, 2) = t_awr3_p2_022
            awr3(3, 3, 1, 2) = t_awr3_p2_022
            awr3(2, 2, 2, 2) = cs85*(cs20*(3.0_wp - cs78) - cs72 - cs79)
            t_awr3_p2_112 = cs80*cs81
            awr3(2, 2, 3, 2) = t_awr3_p2_112
            awr3(2, 3, 2, 2) = t_awr3_p2_112
            awr3(3, 2, 2, 2) = t_awr3_p2_112
            t_awr3_p2_122 = cs84*cs85
            awr3(2, 3, 3, 2) = t_awr3_p2_122
            awr3(3, 2, 3, 2) = t_awr3_p2_122
            awr3(3, 3, 2, 2) = t_awr3_p2_122
            awr3(3, 3, 3, 2) = cs81*(cs20*(3.0_wp - cs82) - cs72 - cs83)
            awr3(1, 1, 1, 3) = cs89*(cs20*(3.0_wp - cs48) - cs86 - cs87)
            t_awr3_p3_001 = cs90*d_a(2)
            awr3(1, 1, 2, 3) = t_awr3_p3_001
            awr3(1, 2, 1, 3) = t_awr3_p3_001
            awr3(2, 1, 1, 3) = t_awr3_p3_001
            t_awr3_p3_002 = cs90*d_a(3)
            awr3(1, 1, 3, 3) = t_awr3_p3_002
            awr3(1, 3, 1, 3) = t_awr3_p3_002
            awr3(3, 1, 1, 3) = t_awr3_p3_002
            t_awr3_p3_011 = cs89*cs92
            awr3(1, 2, 2, 3) = t_awr3_p3_011
            awr3(2, 1, 2, 3) = t_awr3_p3_011
            awr3(2, 2, 1, 3) = t_awr3_p3_011
            t_awr3_p3_012 = cs89*d_a(2)*d_a(3)*(-3.0_wp*cs18 - cs63 - 3.0_wp)
            awr3(1, 2, 3, 3) = t_awr3_p3_012
            awr3(1, 3, 2, 3) = t_awr3_p3_012
            awr3(2, 1, 3, 3) = t_awr3_p3_012
            awr3(2, 3, 1, 3) = t_awr3_p3_012
            awr3(3, 1, 2, 3) = t_awr3_p3_012
            awr3(3, 2, 1, 3) = t_awr3_p3_012
            t_awr3_p3_022 = cs89*cs94
            awr3(1, 3, 3, 3) = t_awr3_p3_022
            awr3(3, 1, 3, 3) = t_awr3_p3_022
            awr3(3, 3, 1, 3) = t_awr3_p3_022
            awr3(2, 2, 2, 3) = cs95*(cs20*(3.0_wp - cs58) - cs86 - cs91)
            t_awr3_p3_112 = cs92*cs96
            awr3(2, 2, 3, 3) = t_awr3_p3_112
            awr3(2, 3, 2, 3) = t_awr3_p3_112
            awr3(3, 2, 2, 3) = t_awr3_p3_112
            t_awr3_p3_122 = cs94*cs95
            awr3(2, 3, 3, 3) = t_awr3_p3_122
            awr3(3, 2, 3, 3) = t_awr3_p3_122
            awr3(3, 3, 2, 3) = t_awr3_p3_122
            awr3(3, 3, 3, 3) = cs96*(cs20*(3.0_wp - cs65) - cs86 - cs93)
            awr3(1, 1, 1, 4) = cs101*(cs20*(3.0_wp - cs97) - cs98 - cs99)
            t_awr3_q_001 = cs103*d_a(2)
            awr3(1, 1, 2, 4) = t_awr3_q_001
            awr3(1, 2, 1, 4) = t_awr3_q_001
            awr3(2, 1, 1, 4) = t_awr3_q_001
            t_awr3_q_002 = cs103*d_a(3)
            awr3(1, 1, 3, 4) = t_awr3_q_002
            awr3(1, 3, 1, 4) = t_awr3_q_002
            awr3(3, 1, 1, 4) = t_awr3_q_002
            t_awr3_q_011 = cs101*cs106
            awr3(1, 2, 2, 4) = t_awr3_q_011
            awr3(2, 1, 2, 4) = t_awr3_q_011
            awr3(2, 2, 1, 4) = t_awr3_q_011
            t_awr3_q_012 = cs107*cs27*(-3.0_wp/2.0_wp*cs18 - 1.0_wp/4.0_wp*cs63 - 3.0_wp)
            awr3(1, 2, 3, 4) = t_awr3_q_012
            awr3(1, 3, 2, 4) = t_awr3_q_012
            awr3(2, 1, 3, 4) = t_awr3_q_012
            awr3(2, 3, 1, 4) = t_awr3_q_012
            awr3(3, 1, 2, 4) = t_awr3_q_012
            awr3(3, 2, 1, 4) = t_awr3_q_012
            t_awr3_q_022 = cs101*cs110
            awr3(1, 3, 3, 4) = t_awr3_q_022
            awr3(3, 1, 3, 4) = t_awr3_q_022
            awr3(3, 3, 1, 4) = t_awr3_q_022
            awr3(2, 2, 2, 4) = cs111*(-cs105 + cs20*(3.0_wp - cs104) - cs98)
            t_awr3_q_112 = cs106*cs107
            awr3(2, 2, 3, 4) = t_awr3_q_112
            awr3(2, 3, 2, 4) = t_awr3_q_112
            awr3(3, 2, 2, 4) = t_awr3_q_112
            t_awr3_q_122 = cs110*cs111
            awr3(2, 3, 3, 4) = t_awr3_q_122
            awr3(3, 2, 3, 4) = t_awr3_q_122
            awr3(3, 3, 2, 4) = t_awr3_q_122
            awr3(3, 3, 3, 4) = cs107*(-cs109 + cs20*(3.0_wp - cs108) - cs98)
         end block
      end select

   end subroutine svdw_atom_radius_tangent_eval

   pure module subroutine svdw_atom_tangent_rad_eval(d_a, R_a, blend_k, v_a, vr_a, max_deriv, awd0, &
                                              awd1, awd2, x_a, inv_x_a, u_a, fade_start, &
                                              fade_width)
      !> Displacement r - R_A of the active atom
      real(wp), intent(in) :: d_a(3)
      !> Radius of the active atom
      real(wp), intent(in) :: R_a
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Nuclear displacement direction of this atom
      real(wp), intent(in) :: v_a(3)
      !> Radius direction of this atom, vr_A = sum_B (dR_A/dX_B) . v_B
      real(wp), intent(in) :: vr_a
      !> Highest spatial-derivative order to set (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> Order-0 radius-differentiated joint contracted kind tensor of this atom
      real(wp), intent(out) :: awd0(nkind)
      !> Order-1 radius-differentiated joint contracted kind tensor of this atom
      real(wp), intent(out) :: awd1(3, nkind)
      !> Order-2 radius-differentiated joint contracted kind tensor of this atom
      real(wp), intent(out) :: awd2(3, 3, nkind)
      !> Distance ||d_a|| of this atom, stage-1 `cache_x` of this point and atom
      real(wp), intent(in) :: x_a
      !> Reciprocal distance 1/x_a, stage-1 `cache_inv_x`; read by the faded branch at orders >= 1
      !> only (Inf on a nucleus)
      real(wp), intent(in) :: inv_x_a
      !> Screening factor exp(-(blend_k/3)(x_a - R_a)) before the fade, gate-masked: stage-1
      !> `cache_u` (inline exp), 0 where the strip's hard screening dropped the atom
      real(wp), intent(in) :: u_a
      !> Fade onset X_on in d_A, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width Delta in d_A, as passed to the strip kernel; > 0
      real(wp), intent(in) :: fade_width

      !> Fade of this atom: band end, reciprocal width, raw and clamped s, t, ds/dd
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k and s**k sqrt(s) of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5, fsp6, fsp7, fsp8, fsp9, fsp10, fsp11, fsp12, fsp13
      real(wp) :: fsp14, fsp15, fsq, fsh3, fsh4, fsh5, fsh6, fsh7

      if (x_a - R_a > fade_start) then
         ! In or beyond the band: faded atom function, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "svdw_atom_tangent_rad_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         inv_delta = 1.0_wp/fade_width
         sr = (band_end - (x_a - R_a))*inv_delta
         fs = min(max(sr, 0.0_wp), 1.0_wp)
         ft = min(max((x_a - R_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
         dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
         fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
         fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
         fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
         fp3 = -1680.0_wp*ft - 210.0_wp
         fp4 = 1680.0_wp
         fsp1 = fs
         fsp2 = fsp1*fs
         fsp3 = fsp2*fs
         fsp4 = fsp3*fs
         fsp5 = fsp4*fs
         fsp6 = fsp5*fs
         fsp7 = fsp6*fs
         fsp8 = fsp7*fs
         fsp9 = fsp8*fs
         fsp10 = fsp9*fs
         fsp11 = fsp10*fs
         fsp12 = fsp11*fs
         fsp13 = fsp12*fs
         fsp14 = fsp13*fs
         fsp15 = fsp14*fs
         fsq = sqrt(fs)
         fsh3 = fsp3*fsq
         fsh4 = fsp4*fsq
         fsh5 = fsp5*fsq
         fsh6 = fsp6*fsq
         fsh7 = fsp7*fsq
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
               real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22

               cs0 = (blend_k*blend_k)
               cs1 = blend_k*dsdd
               cs2 = (dsdd*dsdd)
               cs3 = 20.0_wp*fp0
               cs4 = fp1*fs
               cs5 = &
                  u_a*((1.0_wp/9.0_wp)*cs0*fp0*fsp5 - 2.0_wp/3.0_wp*cs1*(5.0_wp*fp0*fsp4 + &
                  fp1*fsp5) + cs2*fsp3*(cs3 + 10.0_wp*cs4 + fp2*fsp2))
               cs6 = cs5*inv_x_a
               cs7 = d_a(1)*v_a(1)
               cs8 = d_a(2)*v_a(2)
               cs9 = d_a(3)*v_a(3)
               cs10 = (fp0*fp0)
               cs11 = (fp1*fp1)
               cs12 = fp0*fp2
               cs13 = &
                  (u_a*u_a)*((4.0_wp/9.0_wp)*cs0*cs10*fsp10 - 4.0_wp/3.0_wp*cs1*(10.0_wp*cs10*fsp9 &
                  + 2.0_wp*fp0*fp1*fsp10) + 2.0_wp*cs2*fsp8*(45.0_wp*cs10 + cs3*cs4 + fsp2*(cs11 + &
                  cs12)))
               cs14 = cs13*inv_x_a
               cs15 = (fp0*fp0*fp0)
               cs16 = 30.0_wp*cs4
               cs17 = &
                  (u_a*u_a*u_a)*(cs0*cs15*fsp15 - 2.0_wp*cs1*(3.0_wp*cs10*fp1*fsp15 + &
                  15.0_wp*cs15*fsp14) + 3.0_wp*cs2*fp0*fsp13*(70.0_wp*cs10 + cs16*fp0 + &
                  fsp2*(2.0_wp*cs11 + cs12)))
               cs18 = cs17*inv_x_a
               cs19 = (fp0*sqrt(fp0))
               cs20 = sqrt(fp0)
               cs21 = &
                  (u_a*sqrt(u_a))*((1.0_wp/4.0_wp)*cs0*cs19*fsh7 - cs1*((15.0_wp/2.0_wp)*cs19*fsh6 &
                  + (3.0_wp/2.0_wp)*cs20*fp1*fsh7) + (3.0_wp/4.0_wp)*cs2*fsh5*(cs16*cs20 + &
                  65.0_wp*cs19 + fsp2*(cs11/cs20 + 2.0_wp*cs20*fp2)))
               cs22 = cs21*inv_x_a
               awd0(1) = cs5*vr_a + cs6*cs7 + cs6*cs8 + cs6*cs9
               awd0(2) = cs13*vr_a + cs14*cs7 + cs14*cs8 + cs14*cs9
               awd0(3) = cs17*vr_a + cs18*cs7 + cs18*cs8 + cs18*cs9
               awd0(4) = cs21*vr_a + cs22*cs7 + cs22*cs8 + cs22*cs9
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
               real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25
               real(wp) :: cs26, cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37
               real(wp) :: cs38, cs39, cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49
               real(wp) :: cs50, cs51, cs52, cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61
               real(wp) :: cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73
               real(wp) :: cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84, cs85
               real(wp) :: cs86, cs87, cs88

               cs0 = (blend_k*blend_k)
               cs1 = fp0*fsp5
               cs2 = 5.0_wp*fp0*fsp4 + fp1*fsp5
               cs3 = blend_k*dsdd
               cs4 = (dsdd*dsdd)
               cs5 = 20.0_wp*fp0
               cs6 = fp2*fsp2
               cs7 = fp1*fs
               cs8 = cs4*fsp3*(cs5 + cs6 + 10.0_wp*cs7)
               cs9 = (1.0_wp/9.0_wp)*cs0*cs1 - 2.0_wp/3.0_wp*cs2*cs3 + cs8
               cs10 = cs9*u_a
               cs11 = cs10*inv_x_a
               cs12 = d_a(1)*v_a(1)
               cs13 = d_a(2)*v_a(2)
               cs14 = d_a(3)*v_a(3)
               cs15 = (u_a*u_a)
               cs16 = (fp0*fp0)
               cs17 = cs16*fsp10
               cs18 = 10.0_wp*cs16*fsp9 + 2.0_wp*fp0*fp1*fsp10
               cs19 = (fp1*fp1)
               cs20 = fp0*fp2
               cs21 = fsp2*(cs19 + cs20)
               cs22 = cs4*fsp8*(45.0_wp*cs16 + cs21 + cs5*cs7)
               cs23 = (4.0_wp/9.0_wp)*cs0*cs17 - 4.0_wp/3.0_wp*cs18*cs3 + 2.0_wp*cs22
               cs24 = cs15*cs23
               cs25 = cs24*inv_x_a
               cs26 = (u_a*u_a*u_a)
               cs27 = (fp0*fp0*fp0)
               cs28 = cs27*fsp15
               cs29 = 3.0_wp*fp1
               cs30 = cs16*cs29*fsp15 + 15.0_wp*cs27*fsp14
               cs31 = 30.0_wp*cs7
               cs32 = fsp2*(2.0_wp*cs19 + cs20)
               cs33 = cs4*fp0*fsp13*(70.0_wp*cs16 + cs31*fp0 + cs32)
               cs34 = cs0*cs28 - 2.0_wp*cs3*cs30 + 3.0_wp*cs33
               cs35 = cs26*cs34
               cs36 = cs35*inv_x_a
               cs37 = (u_a*sqrt(u_a))
               cs38 = (fp0*sqrt(fp0))
               cs39 = cs38*fsh7
               cs40 = sqrt(fp0)
               cs41 = (15.0_wp/2.0_wp)*cs38*fsh6 + (3.0_wp/2.0_wp)*cs40*fp1*fsh7
               cs42 = 1.0_wp/cs40
               cs43 = fsp2*(cs19*cs42 + 2.0_wp*cs40*fp2)
               cs44 = cs4*fsh5*(cs31*cs40 + 65.0_wp*cs38 + cs43)
               cs45 = (1.0_wp/4.0_wp)*cs0*cs39 - cs3*cs41 + (3.0_wp/4.0_wp)*cs44
               cs46 = cs37*cs45
               cs47 = cs46*inv_x_a
               cs48 = (blend_k*blend_k*blend_k)
               cs49 = (dsdd*dsdd*dsdd)
               cs50 = &
                  -blend_k*cs8 + (1.0_wp/3.0_wp)*cs0*cs2*dsdd - 1.0_wp/27.0_wp*cs1*cs48 + &
                  cs49*fsp2*(15.0_wp*cs6 + 60.0_wp*cs7 + 60.0_wp*fp0 + fp3*fsp3)
               cs51 = (inv_x_a*inv_x_a*inv_x_a)
               cs52 = cs10*cs51
               cs53 = d_a(1)*d_a(2)
               cs54 = (inv_x_a*inv_x_a)
               cs55 = cs50*u_a
               cs56 = cs54*cs55
               cs57 = cs52*cs53 - cs53*cs56
               cs58 = d_a(1)*d_a(3)
               cs59 = cs52*cs58 - cs56*cs58
               cs60 = (d_a(1)*d_a(1))
               cs61 = cs54*cs60
               cs62 = d_a(2)*d_a(3)
               cs63 = cs52*cs62 - cs56*cs62
               cs64 = (d_a(2)*d_a(2))
               cs65 = (d_a(3)*d_a(3))
               cs66 = &
                  -4.0_wp*blend_k*cs22 + (4.0_wp/3.0_wp)*cs0*cs18*dsdd - 8.0_wp/27.0_wp*cs17*cs48 &
                  + 2.0_wp*cs49*fsp7*(360.0_wp*cs16 + 30.0_wp*cs21 + 270.0_wp*cs7*fp0 + &
                  fsp3*(cs29*fp2 + fp0*fp3))
               cs67 = cs24*cs51
               cs68 = cs15*cs66
               cs69 = cs54*cs68
